def compute(vars):
    values = [vars["v1"], vars["v2"], vars["v3"]]
    average_ending_balance = sum(values) / len(values)
    return {
        "value": average_ending_balance,
        "trace": {
            "ending_balances": values,
            "count": len(values),
            "average_ending_balance": average_ending_balance,
            "output_meta": {
                "currency": "USD",
                "scale": "million",
                "unit": None
            }
        }
    }
